"""Procedural Arcade arena floor tiles (WP-tile-floor). Original art generated by this script (no legacy pixels used).
Run: python3 tools/assets/tile-gen/tilefloor.py public/assets/img/tilefloor.png   (needs Pillow + numpy; fixed seed, so the output is byte-identical)
Atlas: 8 columns x 4 rows of 32x32 tiles, rows in stage order (fire, water, earth, air). Columns 0-3 are plain floor variants
(0 the commonest), 4-7 sparse decoration; src/game/fx/terrain-tiles.ts picks them.
"""
import sys
import numpy as np
from PIL import Image, ImageDraw

T = 32
COLS = 8
ROWS = 4

# per stage: base, light (lit edge), dark (shade/joint), accents a, b, c. Grim and desaturated: dark stone, no bright tan.
STAGES = [
    dict(base=(38, 31, 31), light=(52, 43, 41), dark=(16, 12, 13), a=(168, 74, 30), b=(200, 120, 58), c=(44, 18, 12), joint=0),
    dict(base=(26, 36, 44), light=(44, 58, 68), dark=(11, 17, 24), a=(98, 124, 138), b=(150, 172, 184), c=(10, 18, 28), joint=1),
    dict(base=(46, 44, 36), light=(62, 60, 50), dark=(20, 19, 15), a=(56, 70, 40), b=(110, 104, 88), c=(26, 24, 18), joint=1),
    dict(base=(58, 62, 70), light=(78, 83, 92), dark=(30, 33, 40), a=(110, 118, 130), b=(138, 146, 156), c=(36, 40, 48), joint=0),
]


def mix(p, q):
    return tuple(int((p[i] + q[i]) / 2) for i in range(3))


def smooth(rng, cell):
    """Tileable value noise in [0, 1): a (T/cell)^2 random grid, smoothstep-interpolated with wrap-around."""
    n = T // cell
    g = rng.random((n, n))
    u = (np.arange(T) / cell)
    i0 = np.floor(u).astype(int)
    f = u - i0
    f = f * f * (3 - 2 * f)
    i1 = (i0 + 1) % n
    i0 = i0 % n
    top = g[i0][:, i0] * (1 - f)[None, :] + g[i0][:, i1] * f[None, :]
    bot = g[i1][:, i0] * (1 - f)[None, :] + g[i1][:, i1] * f[None, :]
    return top * (1 - f)[:, None] + bot * f[:, None]


def plain(s, rng, variant):
    """A floor tile: wrap-around (so seamless) multi-scale noise plus grain, an occasional joint or pit. No bevel: no grid look."""
    n = smooth(rng, 16) * 0.5 + smooth(rng, 8) * 0.3 + smooth(rng, 4) * 0.2
    shade = ((n - 0.5) * 34 + rng.integers(-3, 4, (T, T)))[:, :, None]
    img = np.clip(np.array(s["base"])[None, None, :] + shade, 0, 255).astype(np.uint8)
    im = Image.fromarray(img, "RGB")
    d = ImageDraw.Draw(im)
    if s["joint"] and variant in (1, 3):
        # A faint flagstone / slate joint across part of the tile.
        y = int(rng.integers(8, T - 8))
        pts = [(0, y)]
        for x in range(6, T + 6, 6):
            y += int(rng.integers(-1, 2))
            pts.append((min(x, T - 1), y))
        d.line(pts, fill=s["dark"], width=1)
        d.line([(x, yy + 1) for x, yy in pts], fill=mix(s["base"], s["light"]), width=1)
    for _ in range(variant * 2):
        x, y = int(rng.integers(3, T - 4)), int(rng.integers(3, T - 4))
        d.point((x, y), fill=s["dark"] if variant % 2 else s["light"])
    return im


def deco(stage, k, s, rng):
    im = plain(s, rng, 0)
    d = ImageDraw.Draw(im)
    a, b, c = s["a"], s["b"], s["c"]

    def zig(pts, col, width=1):
        d.line(pts, fill=col, width=width)

    if stage == 0:  # fire: basalt with ember cracks
        if k == 4:
            p = [(2, 6), (9, 12), (14, 10), (20, 18), (26, 16), (30, 24)]
            zig(p, c, 3); zig(p, a, 1)
        elif k == 5:
            p = [(16, 2), (14, 10), (18, 16), (13, 22), (16, 30)]
            zig(p, c, 3); zig(p, a, 1)
            zig([(18, 16), (26, 18), (30, 14)], a, 1)
        elif k == 6:
            d.ellipse([11, 12, 21, 20], fill=c); d.ellipse([13, 14, 19, 18], fill=a)
        else:
            for _ in range(9):
                x, y = int(rng.integers(2, 30)), int(rng.integers(2, 30))
                d.rectangle([x, y, x + 1, y + 1], fill=a if rng.integers(0, 2) else b)
    elif stage == 1:  # water: ripples, foam, a deep spot, sparkles
        if k == 4:
            d.ellipse([6, 10, 26, 22], outline=a); d.ellipse([11, 13, 21, 19], outline=a)
        elif k == 5:
            for y, x0 in ((8, 2), (16, 9), (24, 4)):
                zig([(x0, y), (x0 + 5, y - 2), (x0 + 11, y), (x0 + 17, y - 2)], a)
        elif k == 6:
            d.ellipse([9, 11, 23, 21], fill=s["dark"]); d.ellipse([12, 13, 20, 19], fill=c)
        else:
            for _ in range(7):
                x, y = int(rng.integers(3, 29)), int(rng.integers(3, 29))
                d.line([(x - 1, y), (x + 1, y)], fill=b); d.line([(x, y - 1), (x, y + 1)], fill=b)
    elif stage == 2:  # earth: pebbles, grass, a crack, a mossy patch
        if k == 4:
            for x, y, r in ((7, 9, 3), (20, 8, 2), (14, 21, 4), (26, 24, 2)):
                d.ellipse([x - r, y - r, x + r, y + r], fill=b, outline=c)
        elif k == 5:
            for x in (10, 15, 20, 24):
                zig([(x, 27), (x + int(rng.integers(-2, 3)), 17)], a, 2)
            zig([(6, 27), (6, 21)], a, 1)
        elif k == 6:
            zig([(3, 4), (10, 11), (9, 18), (17, 24), (24, 29)], c, 2)
            zig([(10, 11), (18, 9), (27, 13)], c, 1)
        else:
            d.ellipse([7, 9, 25, 23], fill=mix(a, s["base"]))
            for _ in range(12):
                x, y = int(rng.integers(6, 26)), int(rng.integers(8, 24))
                d.point((x, y), fill=s["light"])
    else:  # air: cloud wisps
        if k == 4:
            zig([(2, 20), (8, 14), (16, 13), (22, 17), (30, 11)], a, 2); zig([(2, 22), (9, 18), (17, 17)], b, 1)
        elif k == 5:
            for x, y, r in ((10, 18, 6), (18, 14, 7), (24, 19, 5)):
                d.ellipse([x - r, y - r, x + r, y + r], fill=mix(a, s["base"]))
            d.line([(6, 25), (28, 25)], fill=s["dark"])
        elif k == 6:
            d.arc([6, 6, 26, 26], 20, 300, fill=a, width=2); d.arc([11, 11, 21, 21], 200, 460, fill=a, width=1)
        else:
            for _ in range(8):
                x, y = int(rng.integers(3, 29)), int(rng.integers(3, 29))
                d.point((x, y), fill=a); d.point((x + 1, y), fill=a); d.point((x, y + 1), fill=a)
    return im


def main(out):
    rng = np.random.default_rng(20261111)
    sheet = Image.new("RGB", (COLS * T, ROWS * T))
    for stage, s in enumerate(STAGES):
        for k in range(COLS):
            im = plain(s, rng, k) if k < 4 else deco(stage, k, s, rng)
            sheet.paste(im, (k * T, stage * T))
    # Palette-limited PNG (small on disk and gzip): 64 colours, median cut, no dither so it is deterministic.
    sheet.quantize(colors=128, method=Image.Quantize.MEDIANCUT, dither=Image.Dither.NONE).save(out, optimize=True)


main(sys.argv[1])
